window.ScripturaLexicons.BDAG_PART_0035 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anileos-bdag\" data-source=\"BDAG\" data-search=\"ἀνίλεως anileos impiedoso sem misericórdia juízo Tiago variante ἀνέλεος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνίλεως</td><td>Adjetivo</td><td>impiedoso; sem misericórdia</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aniptamai-bdag\" data-source=\"BDAG\" data-search=\"ἀνίπταμαι aniptamai voar para cima esvoaçar filhotes Barnabé Isaías BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνίπταμαι</td><td>Verbo</td><td>voar para cima; esvoaçar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aniptos-bdag\" data-source=\"BDAG\" data-search=\"ἄνιπτος aniptos não lavado mãos lavar refeição Mateus Marcos tradição rabínica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄνιπτος</td><td>Adjetivo</td><td>não lavado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anistemi-bdag\" data-source=\"BDAG\" data-search=\"ἀνίστημι anistemi erguer levantar ressuscitar gerar suscitar edificar levantar-se ressurgir aparecer iniciar ação Atos João Marcos Lucas Mateus Romanos Efésios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνίστημι</td><td>Verbo</td><td>erguer; levantar-se; ressuscitar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hanna-bdag\" data-source=\"BDAG\" data-search=\"Ἅννα Hanna Ana profetisa filha Fanuel mãe Maria Protoevangelho Tiago Lucas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἅννα</td><td>Nome próprio feminino</td><td>Ana</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hannas-bdag\" data-source=\"BDAG\" data-search=\"Ἅννας Hannas Anás sumo sacerdote Caifás escriba Lucas João Atos Protoevangelho Tiago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἅννας</td><td>Nome próprio masculino</td><td>Anás</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anodia-bdag\" data-source=\"BDAG\" data-search=\"ἀνοδία anodia lugar sem estradas região intransitável Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνοδία</td><td>Substantivo feminino</td><td>lugar sem estradas; região intransitável</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoetos-bdag\" data-source=\"BDAG\" data-search=\"ἀνόητος anoetos sem inteligência insensato tolo obtuso Romanos Lucas Gálatas Tito Timóteo Clemente Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνόητος</td><td>Adjetivo</td><td>insensato; tolo; obtuso</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoia-bdag\" data-source=\"BDAG\" data-search=\"ἄνοια anoia insensatez ignorância fúria Lucas 6.11 2 Timóteo 3.9 2 Clemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄνοια</td><td>Substantivo feminino</td><td>insensatez; ignorância; fúria</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoigo-bdag\" data-source=\"BDAG\" data-search=\"ἀνοίγω anoigo abrir porta céu sepulcro tesouro livro selo boca olhos ouvidos coração oportunidade Atos João Mateus Lucas Apocalipse Coríntios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνοίγω</td><td>Verbo</td><td>abrir; tornar acessível; estar aberto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoikodomeo-bdag\" data-source=\"BDAG\" data-search=\"ἀνοικοδομέω anoikodomeo reconstruir reedificar tabernáculo Davi ruínas templo Atos Judas Barnabé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνοικοδομέω</td><td>Verbo</td><td>reconstruir; reedificar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoixis-bdag\" data-source=\"BDAG\" data-search=\"ἄνοιξις anoixis ato de abrir abertura boca Efésios 6.19 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄνοιξις</td><td>Substantivo feminino</td><td>ato de abrir; abertura</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoiso-bdag\" data-source=\"BDAG\" data-search=\"ἀνοίσω anoiso veja ἀναφέρω remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνοίσω</td><td>Remissão</td><td>veja ἀναφέρω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoichthesomai-bdag\" data-source=\"BDAG\" data-search=\"ἀνοιχθήσομαι anoichthesomai veja ἀνοίγω remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνοιχθήσομαι</td><td>Remissão</td><td>veja ἀνοίγω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anomeo-bdag\" data-source=\"BDAG\" data-search=\"ἀνομέω anomeo agir sem lei pecar transgredir iniquidade Hermas Clemente Barnabé Protoevangelho Tiago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνομέω</td><td>Verbo</td><td>agir sem lei; pecar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anomema-bdag\" data-source=\"BDAG\" data-search=\"ἀνόμημα anomema ato ilícito iniquidade pecado Hermas Clemente Salmos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνόμημα</td><td>Substantivo neutro</td><td>ato ilícito; iniquidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anomia-bdag\" data-source=\"BDAG\" data-search=\"ἀνομία anomia iniquidade ilegalidade transgressão ato ilícito sem lei Anticristo Satanás Romanos Coríntios Mateus João Tito Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνομία</td><td>Substantivo feminino</td><td>iniquidade; ilegalidade; ato ilícito</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anomoios-bdag\" data-source=\"BDAG\" data-search=\"ἀνόμοιος anomoios diferente dessemelhante estrela Inácio Efésios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνόμοιος</td><td>Adjetivo</td><td>diferente; dessemelhante</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anomos-bdag\" data-source=\"BDAG\" data-search=\"ἄνομος anomos sem lei ilegal ímpio perverso gentio Anticristo Romanos Coríntios Timóteo Marcos Lucas Atos Barnabé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄνομος</td><td>Adjetivo</td><td>sem lei; ilegal; ímpio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anomos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀνόμως anomos advérbio sem lei ilegalmente sistema jurídico lei mosaica Romanos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνόμως</td><td>Advérbio</td><td>sem lei; à margem da lei</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoneidistos-bdag\" data-source=\"BDAG\" data-search=\"ἀνονειδίστως anoneidistos sem censurar sem lançar em rosto liberalmente Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνονειδίστως</td><td>Advérbio</td><td>sem censurar; sem lançar em rosto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anonetos-bdag\" data-source=\"BDAG\" data-search=\"ἀνόνητος anonetos inútil desejos nocivos 1 Timóteo variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνόνητος</td><td>Adjetivo</td><td>inútil</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anorthoo-bdag\" data-source=\"BDAG\" data-search=\"ἀνορθόω anorthoo reconstruir restaurar endireitar erguer fortalecer Atos Lucas Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνορθόω</td><td>Verbo</td><td>reconstruir; restaurar; endireitar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anosios-bdag\" data-source=\"BDAG\" data-search=\"ἀνόσιος anosios profano ímpio perverso sagrado Deus Timóteo Clemente Atos de Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνόσιος</td><td>Adjetivo</td><td>profano; ímpio; perverso</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anoche-bdag\" data-source=\"BDAG\" data-search=\"ἀνοχή anoche alívio trégua pausa tolerância clemência longanimidade Romanos Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνοχή</td><td>Substantivo feminino</td><td>alívio; pausa; tolerância</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antagonizomai-bdag\" data-source=\"BDAG\" data-search=\"ἀνταγωνίζομαι antagonizomai lutar combater pecado Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνταγωνίζομαι</td><td>Verbo</td><td>lutar contra</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antakouo-bdag\" data-source=\"BDAG\" data-search=\"ἀντακούω antakouo ouvir em resposta ouvir por sua vez Clemente Jó BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀντακούω</td><td>Verbo</td><td>ouvir em resposta</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antallage-bdag\" data-source=\"BDAG\" data-search=\"ἀνταλλαγή antallage troca intercâmbio doce troca Diogneto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνταλλαγή</td><td>Substantivo feminino</td><td>troca</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antallagma-bdag\" data-source=\"BDAG\" data-search=\"ἀντάλλαγμα antallagma algo dado em troca compensação alma Mateus Marcos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀντάλλαγμα</td><td>Substantivo neutro</td><td>algo dado em troca; compensação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antanairo-bdag\" data-source=\"BDAG\" data-search=\"ἀνταναιρέω antanaireo retirar tirar punição Clemente Salmo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνταναιρέω</td><td>Verbo</td><td>retirar como punição</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antanapleroo-bdag\" data-source=\"BDAG\" data-search=\"ἀνταναπληρόω antanapleroo completar por sua parte suprir tribulações Cristo Colossenses sofrimentos messiânicos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνταναπληρόω</td><td>Verbo</td><td>completar por sua parte; suprir</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-anileos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνίλεως</h1><div class=\"entry-meta\"><span class=\"greek\">gen. ω</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aníleōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Impiedoso, sem misericórdia.</strong> Herodiano [?], <em>Epim.</em> [= <em>Partitiones</em>] 257 JBoissonade; TestGad 5.11; TestAbr A 12 p. 91, 7 [Stone p. 30] e outros; ApcEsdr 4.9 p. 28, 9 Tdf., <span class=\"greek\">κρίσις</span>. <span class=\"greek\">κρίσις</span>, Tg 2.13 v.l., em lugar de <span class=\"greek\">ἀνέλεος</span>, veja esse verbete. — DELG s.v. <span class=\"greek\">ἱλάσκομαι</span>.</p>\n</section></article><article id=\"entry-aniptamai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνίπταμαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aníptamai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀνά</span> + <span class=\"greek\">πέτομαι</span>; Máximo de Tiro 20.6d; Cássio Dio 56.42.3; Temístio 27 p. 406, 11 D.; <em>Cyranides</em> 3 p. 100, 11; sobre a forma em lugar de <span class=\"greek\">ἀναπέτομαι</span>, Kühner-Bl. II 450. <strong>Voar para cima, esvoaçar.</strong> <span class=\"greek\">νοσσοὶ ἀνιπτάμενοι</span>, <strong>filhotes esvoaçando</strong>, B 11.3 (Is 16.2). — Lampe. Frisk s.v. <span class=\"greek\">πέτομαι</span>.</p>\n</section></article><article id=\"entry-aniptos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄνιπτος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ániptos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀ-</span> privativo + <span class=\"greek\">νίπτω</span>; Homero e outros. <strong>Não lavado.</strong> <span class=\"greek\">χεῖρες</span>, <strong>mãos</strong>, <em>Il.</em> 6.266; Fílon, <em>Spec. Leg.</em> 2.6; Mt 15.20. <span class=\"greek\">κοιναῖς χερσίν, τουτέστιν ἀνίπτοις</span>, Mc 7.2, 5 v.l. Segundo uma regra rabínica que ia além da Torá, era necessário lavar as mãos antes da refeição; veja Schürer II 477. — DELG s.v. <span class=\"greek\">νίπτω</span>. TW.</p>\n</section></article><article id=\"entry-anistemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνίστημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anístēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀνά</span> + <span class=\"greek\">ἵστημι</span>; Homero e posteriores. Futuro <span class=\"greek\">ἀναστήσω</span>; 1º aoristo <span class=\"greek\">ἀνέστησα</span>; perfeito 3ª sg. <span class=\"greek\">ἀνέστακεν</span>, 1Km 15.12; 2º aoristo <span class=\"greek\">ἀνέστην</span>, imperativos <span class=\"greek\">ἀνάστηθι</span> e <span class=\"greek\">ἀνάστα</span>, Ef 5.14; At 9.11 v.l.; 11.7 v.l.; 12.7; compare TestAbr B 2 p. 106, 2 [Stone p. 60] e outros; ParJer 1.1 em oposição ao v. 10. Particípio <span class=\"greek\">ἀναστάς</span>; W-S. §14, 15; B-D-F §95, 3. Futuro médio <span class=\"greek\">ἀναστήσομαι</span>; aoristo passivo subjuntivo 3ª sg. <span class=\"greek\">ἀνασταθῇ</span>, 1Esd 2.18; particípio neutro <span class=\"greek\">ἀνασταθέντα</span>, 2Mc 5.16. Transitivo nos sentidos 1–5: futuro e 1º aoristo ativos; intransitivo nos sentidos 6–11: 2º aoristo e todas as formas médias.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Fazer ficar de pé ou ereto, levantar, erigir</strong>, transitivo. <strong>a.</strong> De imagens de divindades, frequentemente de estátuas: SIG 867, 68; 1073, 45; BGU 362 VI, 4 e outros; PtK 2 p. 14, 16; Ath. 26.2 [passivo]. <strong>b.</strong> De alguém deitado, especialmente doente: Artemidoro 2.37 p. 139, 23 <span class=\"greek\">τοὺς νοσοῦντας ἀνίστησιν</span>; Josefo, <em>Ant.</em> 7.193. <span class=\"greek\">δοὺς αὐτῇ χεῖρα ἀνέστησεν αὐτήν</span>, <strong>deu-lhe a mão e levantou-a</strong>, At 9.41.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Levantar trazendo de volta à vida, ressuscitar, levantar</strong>, transitivo; especialmente dos mortos, <strong>ressuscitar, trazer à vida</strong>: Ps.-Xenofonte, <em>Cyn.</em> 1.6; Pausânias 2.26.5 [Asclépio] <span class=\"greek\">ἀνίστησι τεθνεῶτας</span>; Aélio Aristides 45, 29 K. = 8 p. 95 D.; Palaeph. p. 35, 8; Himerius, <em>Or.</em> [<em>Ecl.</em>] 5.32; 2Mc 7.9; Justino, <em>D.</em> 46.7 e outros; Orígenes, <em>C. Cels.</em> 2.48.20; Jo 6.39s., 44, 54; em forma plena <span class=\"greek\">ἀ. ἐκ νεκρῶν</span>, At 13.34; compare Herodas 1.43 <span class=\"greek\">ἐκ νερτέρων ἀνίστημί τινα</span>. Especialmente da ressurreição de Jesus: At 2.24, 30 v.l., 32; 3.26, em jogo de palavras com v. 22; 13.33s.; 17.31. Inácio diz de Jesus <span class=\"greek\">ἀνέστησεν ἑαυτόν</span>, ISm 2; compare Theodore Prodr. 5, 88 H.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Fazer nascer, suscitar descendência</strong>, transitivo, na expressão <span class=\"greek\">ἀνιστάναι σπέρμα</span>, <strong>suscitar semente = gerar, procriar</strong>; <span class=\"greek\">σπέρμα τῷ ἀδελφῷ</span>, <strong>filhos para o irmão</strong>, Mt 22.24 (Gn 38.8), com referência ao levirato. De procriação em geral, <span class=\"greek\">σπέρμα ἐν τῷ Ἰσραὴλ ἀνέστησαν</span>, <strong>os justos deixaram descendentes em Israel</strong>, GJs 1.3; veja <span class=\"greek\">ἐξανίστημι</span> 2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Fazer aparecer para uma função ou papel, suscitar</strong>, transitivo: Plutarco, <em>Marcell.</em> 314 [27.2]; Sinésio, <em>Ep.</em> 67 p. 210c; EpJer 52; PsSol 17.21; compare Did., <em>Gen.</em> 139, 7. <span class=\"greek\">προφήτην ὑμῖν</span>, <strong>suscitar-vos um profeta</strong>, At 3.22, após Dt 18.15 e em jogo de palavras com At 3.26; veja 2 acima. Por eleição, <span class=\"greek\">τίνα ἀναστήσουσιν εἰς τὸν τόπον τοῦ Ζαχαρίου</span>, GJs 24.4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> <strong>Erigir uma estrutura</strong>, transitivo: Josefo, <em>Ant.</em> 19.329 <span class=\"greek\">ναούς</span>; Mc 14.58 D.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">6.</span> <strong>Levantar-se de posição reclinada ou sentada, ficar de pé, levantar-se para falar</strong>, intransitivo: Xenofonte, <em>An.</em> 3.2.34 <span class=\"greek\">ἀναστὰς εἶπε</span>. <span class=\"greek\">ἀναστὰς ὁ ἀρχιερεὺς εἶπεν</span>, <strong>levantando-se, o sumo sacerdote disse</strong>, Mt 26.62; compare Mc 14.57, 60; Lc 17.12 v.l. De sair da cama, Lc 11.7, 8; compare 2Km 11.2 e, de Deus, Justino, <em>D.</em> 127.2 <span class=\"greek\">οὔτε καθεύδει οὔτε ἀνίσταται</span>. Levantar-se e reunir-se para consulta, At 26.30. De quem se recupera de doença, Mc 9.27, ou retorna à vida: <span class=\"greek\">ἀνέστη τὸ κοράσιον</span>, <strong>a menina levantou-se</strong>, Mc 5.42; compare Lc 8.55. Com infinitivo de finalidade: <span class=\"greek\">ἀ. ἀναγνῶναι</span>, <strong>levantar-se para ler</strong> a Escritura, Lc 4.16; <span class=\"greek\">ἀ. παίζειν</span>, 1Co 10.7 (Êx 32.6); <span class=\"greek\">ἀ. ἄρχειν</span>, Rm 15.12 (Is 11.10). Abreviação de <strong>levantar-se e ir</strong>: <span class=\"greek\">ἀναστὰς ὁ ἀρχιερεὺς εἰς μέσον</span>, <strong>levantou-se e foi ao meio</strong>, Mc 14.60; <span class=\"greek\">ἀ. ἀπὸ τῆς συναγωγῆς</span>, Lc 4.38; <span class=\"greek\">ἀ. ἀπὸ τῆς προσευχῆς</span>, 22.45; <span class=\"greek\">ἀπὸ τοῦ σάκκου</span>, GJs 13.2; <span class=\"greek\">ἀπο τοῦ ὕπνου</span>, 14.2. De uma árvore inclinada que volta a erguer-se, B 12.1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">7.</span> <strong>Voltar à vida dentre os mortos, levantar-se, ressurgir dentre os mortos</strong>, intransitivo: <em>Il.</em> 21.56; Heródoto 3.62.4; Jo 11.23s.; 1Co 15.51 D; PBrandhuber, <em>Biblica</em> 18, 1937, 303–33; 418–38; 1Ts 4.16; IRo 4.3; ISm 7.1; B 11.7 (Sl 1.5); 2Cl 9.1; AcPl BMM verso 38. Em forma plena, <span class=\"greek\">ἐκ νεκρῶν ἀ.</span>, Mc 9.10; 12.25; Qua (apolog.); Lc 16.30 v.l. com <span class=\"greek\">ἀπό</span>. Particípio da ressurreição de Jesus: Mt 17.9 v.l.; 20.19 v.l.; Mc 8.31; 9.9s., 31; 10.34; 16.9; Lc 18.33; 24.7, 46; Jo 20.9; At 17.3; Rm 14.9 v.l.; 1Ts 4.14; IRo 6.1; B 15.9. Intransitivo usado pelo passivo: <span class=\"greek\">ὑπὸ τ. θεοῦ ἀναστάντα</span>, <strong>ressuscitado por Deus</strong>, Pol 9.2; <span class=\"greek\">περὶ τῶν ὑπὸ τοῦ χριστοῦ ἐκ νεκρῶν ἀναστάντων</span>, Papias 11.2. Figuradamente, de reavivamento espiritual: <span class=\"greek\">ἀνάστα ἐκ τ. νεκρῶν</span>, <strong>levanta-te dentre os mortos</strong>, Ef 5.14; compare Cleopatra l. 127s. e Rtzst., <em>Erlösungsmyst.</em> 6; 135ss. Para bibliografia, veja <span class=\"greek\">ἀνάστασις</span>, final.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">8.</span> <strong>Mostrar-se disposto a ajudar, erguer-se</strong>, intransitivo; para ajudar o pobre, de Deus, 1Cl 15.6 (Sl 11.6).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">9.</span> <strong>Vir/aparecer para exercer função ou papel, erguer-se, surgir</strong>, intransitivo: 1Mc 2.1; 14.41; Jdt 8.18; 1Esd 5.40. De rei, At 7.18 (Êx 1.8). De sacerdote, Hb 7.11, 15. De acusadores em tribunal, Mt 12.41; Lc 11.32; Mc 14.57; compare o uso de קום, “levantar-se”, em 11Q Temple 61, 7. De um questionador que surge num grupo de discípulos, Lc 10.25; compare At 6.9. De inimigo, <span class=\"greek\">ἀ. ἐπί τινα</span>, <strong>erguer-se ou rebelar-se contra alguém</strong>, Mc 3.26; compare Gn 4.8; 2Cr 20.23; Sus 61 Theod.; ApcEsdr 3.12 p. 27, 23 Tdf.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">10.</span> <strong>Iniciar uma ação</strong>, intransitivo, com enfraquecimento do sentido básico, para indicar o começo de uma ação, geralmente movimento, expressa por outro verbo: <strong>levantar-se, partir, preparar-se</strong>. Xenofonte, <em>Cyr.</em> 5.2.14; Gn 13.17; 19.14; 1Mc 16.5; Tb 8.10; 10.10; Sus 19 Theod.; Josefo, <em>Ant.</em> 14.452; Justino, <em>D.</em> 9.2. <span class=\"greek\">ἀναστὰς ἠκολούθησεν αὐτῷ</span>, <strong>preparou-se e o seguiu</strong>, Mt 9.9; Lc 5.28; Mc 2.14. <span class=\"greek\">ἀ. ἐξῆλθεν</span>, Mc 1.35; <span class=\"greek\">ἀ. ἀπῆλθεν</span>, 7.24; <span class=\"greek\">ἀ. ἔρχεται</span>, 10.1; <span class=\"greek\">ἀ. ἔδραμεν</span>, Lc 24.12; <span class=\"greek\">ἀναστᾶσα ἐπορεύθη</span>, Lc 1.39, compare 15.18; <span class=\"greek\">ἀναστάντες ἐξέβαλον</span>, 4.29; <span class=\"greek\">ἀναστᾶσα διηκόνει</span>, v. 39; <span class=\"greek\">ἀ. ἔστη</span>, 6.8; <span class=\"greek\">ἀ. ἦλθεν</span>, 15.20; <span class=\"greek\">ἀνάστηθι καὶ πορεύου</span>, <strong>levanta-te e vai!</strong>, At 8.26, compare 27; <span class=\"greek\">ἀναστὰς πορεύθητι</span>, 9.11, com v.l. <span class=\"greek\">ἀνάστα πορ.</span>; <span class=\"greek\">ἀνάστηθι καὶ εἴσελθε</span>, v. 6; <span class=\"greek\">ἀνάστηθι καὶ στρῶσον</span>, v. 34; <span class=\"greek\">ἀναστὰς κατάβηθι</span>, 10.20 e outros.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">11.</span> <strong>Tornar-se uma estrutura erguida, levantar-se, elevar-se</strong>, intransitivo: Melito, <em>P.</em> 36 <span class=\"greek\">ἔργον</span>; Mc 13.2 v.l. — Dalman, <em>Worte</em> 18s. B. 668. DELG s.v. <span class=\"greek\">ἵστημι</span>. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-hanna-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἅννα</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Hánna⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Variante editorial <span class=\"greek\">Ἄν-</span>; hebraico <span lang=\"he\" dir=\"rtl\">חַנָּה</span>. 1Km 1.2ss.; Fílon, <em>Deus Imm.</em> 5ss.; <em>Ebr.</em> 145ss.; <em>Mut. Nom.</em> 143s.; <em>Somn.</em> 1.254; Josefo, <em>Ant.</em> 5.342; 344–47; BCH 3, 1879, p. 344, 23; ISyriaW 1965; frequentemente em papiros, veja Preis., <em>Namenbuch</em>. <strong>Hannah</strong>, ou <strong>Ana</strong> segundo a Vulgata e numerosas outras traduções; veja B-D-F §39, 3; 40; 53, 3. <span class=\"sense-number\">1.</span> Profetisa, filha de Fanuel, Lc 2.36. <span class=\"sense-number\">2.</span> Mãe de Maria, mãe de Jesus, GJs 2.1, 3, 4; 3.1; 4.1, 2, 4; 5.2; 6.3; 7.1.</p>\n</section></article><article id=\"entry-hannas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἅννας</h1><div class=\"entry-meta\"><span class=\"greek\">α, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Hánnas⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Variante editorial <span class=\"greek\">Ἄν-</span>; Herodas 8.14; 43; 66, como nome masculino, acentuado <span class=\"greek\">Ἀννᾶς</span> pelas edições; PGen 42, 8; inscrição cipriota de templo egípcio, Κυπρ. I p. 293 nº 21. <span class=\"sense-number\">1.</span> <strong>Hannas ou Anás</strong>; veja B-D-F §40; 53, 2; Rob. 225; forma abreviada de <span class=\"greek\">Ἅνανος</span>, <strong>“YHWH é gracioso”</strong>. Sumo sacerdote entre 6–15 d.C., Lc 3.2; Jo 18.24; At 4.6. Sogro de Caifás, Jo 18.13. Compare Josefo, <em>Ant.</em> 18.26; 20.197; Schürer II 216; 230; 232–34; PGaechter, <em>Petrus u. seine Zeit</em>, 1958, 67–104. <span class=\"sense-number\">2.</span> <strong>Anás</strong>, nome de um erudito das Escrituras ou escriba, GJs 15.1.</p>\n</section></article><article id=\"entry-anodia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνοδία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anodía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Políbio 5.13.6 e outros; Diodoro Sículo 19.5.3; Plutarco, <em>Mar.</em> 427 [37.9], <em>Mor.</em> 508d; Jó 12.24 Sym.; En 89.44. <strong>Lugar sem estradas, região intransitável.</strong> Hv 1.1.3; em oposição a <span class=\"greek\">ὁδός</span>, Fílon, <em>Somn.</em> 2.161; <em>Mos.</em> 2.138; Hv 3.2.9. Plural, Josefo, <em>Bell.</em> 4.109; Hv 3.7.1; Hm 6.1.3. — DELG s.v. <span class=\"greek\">ὁδός</span>. TW.</p>\n</section></article><article id=\"entry-anoetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνόητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anóētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">νόημα</span>; predominantemente, e na literatura tratada sempre, em sentido ativo, como nos pré-socráticos, Sófocles; Platão, <em>Gorg.</em> 464d e outros; LXX; EpArist 136; Fílon; Josefo, <em>Ant.</em> 9.225, <em>C. Ap.</em> 2.255; Justino, <em>D.</em> 64.5; Taciano 16.1; Atanásio. <strong>Sem inteligência, insensato, tolo, obtuso.</strong></p>\n<p class=\"entry-text\"><strong>a.</strong> De pessoas, em oposição a <span class=\"greek\">σοφός</span>, compare Pv 17.28; Rm 1.14; com <span class=\"greek\">ἄφρων</span>, Plutarco, <em>Mor.</em> 22c <span class=\"greek\">τοῖς ἄφροσι καὶ ἀνοήτοις</span>; Epicteto 2.21.1; 1Cl 21.5; com <span class=\"greek\">βραδὺς τ. καρδίᾳ</span>, Lc 24.25. Em tratamento direto, Diógenes Laércio 2.117 <span class=\"greek\">ἀνόητε</span> = <strong>tolo!</strong>; 4Mc 8.17; 1Cl 23.4; 2Cl 11.3; Hm 10.2.1; Gl 3.1; compare Chariton 6.7.9; Alciphron 4.7.4; Filóstrato, <em>Vi. Apoll.</em> 8.7 p. 307, 13 <span class=\"greek\">ὦ ἀνόητοι</span>; Fílon, <em>Somn.</em> 2.181 <span class=\"greek\">ὦ ἀνόητε</span>; e Gl 3.3. Da condição intelectual e espiritual anterior à conversão: <span class=\"greek\">ἦμεν γάρ ποτε καὶ ἡμεῖς ἀ.</span>, Tt 3.3; compare Herm. Wr. 1.23.</p>\n<p class=\"entry-text\"><strong>b.</strong> Com substantivo que denota coisa: Sófocles, <em>Ajax</em> 162 <span class=\"greek\">γνῶμαι</span>; Justino, <em>D.</em> 68.8 <span class=\"greek\">γνώμην</span>; Platão, <em>Phileb.</em> 12d <span class=\"greek\">δόξαι</span>; Herm. Wr. 6.3b; Justino, <em>D.</em> 23.1; 68.9; 80.3. <span class=\"greek\">ἐπιθυμίας ἀ.</span>, <strong>desejos insensatos</strong>, 1Tm 6.9, v.l. <span class=\"greek\">ἀνονήτους</span>. — B. 1215. DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW.</p>\n</section></article><article id=\"entry-anoia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄνοια</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánoia⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">“Característica de quem é <span class=\"greek\">ἄνοος</span>”, isto é, sem entendimento; veja <span class=\"greek\">νοῦς</span>. Teógnis 453 e outros; Platão, <em>Tim.</em> 86b <span class=\"greek\">δύο ἀνοίας γένη, τὸ μὲν μανία, τὸ δ’ ἀμαθία</span>; Herm. Wr. 14.8; LXX; Fílon; Josefo, <em>Bell.</em> 2.110, <em>C. Ap.</em> 2.10; Ar. 9.5 <span class=\"greek\">ὢ τῆς ἀ.</span>. <strong>Insensatez</strong> de mestres exploradores e dissidentes, 2Tm 3.9; AcPlCor 1.16. Em geral, da ignorância humana, com <span class=\"greek\">πονηρία</span>, Josefo, <em>Ant.</em> 8.318; 2Cl 13.1. De pessoas iradas, <span class=\"greek\">ἐπλήσθησαν ἀνοίας</span>, <strong>encheram-se de fúria</strong>, Lc 6.11; compare PEg² 51, leitura do manuscrito; para a restauração <span class=\"greek\">[δι]|άνοια</span>, veja esse verbete. — DELG s.v. <span class=\"greek\">νόος</span>. TW.</p>\n</section></article><article id=\"entry-anoigo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνοίγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anoígō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀνά</span> + <span class=\"greek\">οἴγω</span>, <strong>“abrir”</strong>; Homero e posteriores. Sobre esta forma variante de <span class=\"greek\">ἀνοίγνυμι</span>, veja Kühner-Bl. II 496s.; W-S. §12, 7 e §15 (p. 130); B-D-F §101; Rob. 1212s.; Mayser 404. Futuro <span class=\"greek\">ἀνοίξω</span>; 1º aoristo <span class=\"greek\">ἀνέῳξα</span>, Jo 9.14, variantes <span class=\"greek\">ἠνέῳξα</span>, <span class=\"greek\">ἤνοιξα</span>; <span class=\"greek\">ἠνέῳξα</span> no v. 17, variantes <span class=\"greek\">ἤνοιξα</span>, <span class=\"greek\">ἀνέῳξα</span>; predominantemente <span class=\"greek\">ἤνοιξα</span>, At 5.19; 9.40 e outros. 2º perfeito intransitivo <span class=\"greek\">ἀνέῳγα</span>; perfeito passivo <span class=\"greek\">ἀνέῳγμαι</span>, 2Co 2.12, v.l. <span class=\"greek\">ἠνέῳγμαι</span>; particípio <span class=\"greek\">ἀνεῳγμένος</span>, com <span class=\"greek\">ἠνεῳγμένος</span> em 3Km 8.52 e <span class=\"greek\">ἠνοιγμένος</span> em Is 42.20; infinitivo <span class=\"greek\">ἀνεῴχθαι</span>, Justino, <em>D.</em> 123.2. Passivo: 1º aoristo <span class=\"greek\">ἠνεῴχθην</span>, Mt 3.16; v.l. 9.30; Jo 9.10; At 16.26, variantes <span class=\"greek\">ἀνεῴχθην</span>, <span class=\"greek\">ἠνοίχθην</span>; infinitivo <span class=\"greek\">ἀνεῳχθῆναι</span>, Lc 3.21, <span class=\"greek\">ἀνοιχθῆναι</span> D; 1º futuro <span class=\"greek\">ἀνοιχθήσομαι</span>, Lc 11.9s. v.l.; 2º aoristo <span class=\"greek\">ἠνοίγην</span>, Mc 7.35, variantes <span class=\"greek\">ἠνοίχθησαν</span>, <span class=\"greek\">διηνοίγησαν</span>, <span class=\"greek\">διηνοίχθησαν</span>; At 12.10, v.l. <span class=\"greek\">ἠνοίχθη</span>; Hv 1.1.4; 2º futuro <span class=\"greek\">ἀνοιγήσομαι</span>, Mt 7.7; Lc 11.9s., v.l. <span class=\"greek\">ἀνοίγεται</span>. A mesma situação ocorre na LXX: Helbing 78s.; 83ss.; 95s.; 102s.; Thackeray 202ss.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Mover algo de uma posição fechada, abrir</strong>, transitivo. De porta: Menandro, <em>Epitr.</em> 643 Kö.; Políbio 16.25.7; OGI 222, 36; 332, 28; SIG 798, 19; 1Km 3.15; PsSol 8.17; GrBar 11.5s.; Josefo, <em>Ant.</em> 13.92; <em>Vi.</em> 246; Justino, <em>D.</em> 36.5 <span class=\"greek\">τὰς πύλας τῶν οὐρανῶν</span>. <span class=\"greek\">τὰς θύρας</span>, literalmente as folhas de uma porta dupla, At 5.19; 12.10, com força ativa; 16.26s.; veja OWeinreich, <em>Türöffnung im Wunder-, Prodigien- u. Zauberglauben d. Antike, d. Judentums u. Christentums</em>, WSchmid Festschr. 1929, 200–452. <span class=\"greek\">ἀ. τὸν πυλῶνα</span>, <strong>abrir a porta exterior da casa</strong>, At 12.14. <span class=\"greek\">τ. θύραν τ. ναοῦ</span>, figuradamente da boca do crente, que é o templo de Deus, B 16.9; compare Philosoph. Max. 488, 6. Sem “porta” como objeto acusativo, ou como sujeito de verbo passivo, facilmente suprida pelo contexto: Aquiles Tácio 2.26.1; Mt 7.7s.; Lc 11.9s.; Mt 25.11; Lc 13.25; GJs 12.2.</p>\n<p class=\"entry-text\">Usado figuradamente de vários modos: PTebt 383, 29 [46 d.C.]; Epicteto, índice de Schenkl, <span class=\"greek\">ἡ θύρα ἤνοικται</span> = <strong>sou livre para ir a qualquer lugar</strong>; Ap 3.20; compare 3.7s.; Is 22.22; Jó 12.14. <span class=\"greek\">πύλη δικαιοσύνης</span>, 1Cl 48.2, compare 4. Da pregação que conquista atenção: <span class=\"greek\">ἤνοιξεν τοῖς ἔθνεσιν θύραν πίστεως</span>, <strong>Deus abriu aos gentios uma porta de fé</strong>, isto é, deu-lhes oportunidade de tornar-se crentes, At 14.27. <span class=\"greek\">θύρας μοι ἀνεῳγμένης</span>, <strong>uma porta foi aberta para mim</strong>, isto é, foi-me dada oportunidade de trabalhar, 2Co 2.12; para 1Co 16.9, veja 6 abaixo. Igualmente <span class=\"greek\">ἀ. θύραν τοῦ λόγου</span>, Cl 4.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Tornar algo prontamente acessível, abrir</strong>, transitivo, de lugares fechados cujo interior assim se torna acessível: um santuário, 1Cl 43.5; passivo, Ap 11.19; 15.5; o céu, Kaibel 882 [século III d.C.] <span class=\"greek\">οὐρανὸν ἀνθρώποις εἶδον ἀνοιγόμενον</span>; PGM 4, 1180; 36, 298; Is 64.1; Ez 1.1; compare 3Mc 6.18; Mt 3.16; Lc 3.21; At 10.11; Ap 19.11; GEb 18, 36; Hv 1.1.4; o mundo inferior, Ap 9.2; sepulcros, SIG 1237, 3 <span class=\"greek\">ἀνοῖξαι τόδε τὸ μνῆμα</span>; Ez 37.12, 13; Mt 27.52. Figuradamente, da garganta dos ímpios: <span class=\"greek\">τάφος ἀνεῳγμένος ὁ λάρυγξ αὐτῶν</span>, <strong>a garganta deles é sepulcro aberto</strong>, talvez exalando putrefação, Rm 3.13 (Sl 5.10; 13.3).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Revelar o conteúdo abrindo, abrir</strong>, transitivo. <span class=\"greek\">τ. θησαυρούς</span>, <strong>tesouros</strong>, SIG² 587, 302; 601, 32; 653, 93; Eurípides, <em>Ion</em> 923; Arriano, <em>Cyneg.</em> 34.2; Is 45.3; Sir 43.14; Fílon, <em>Leg. All.</em> 3.105; Ath. 1.1; Mt 2.11. <span class=\"greek\">κεράμιον οἴνου ἢ ἐλαίου</span>, <strong>abrir um jarro de vinho ou óleo</strong>, D 13.6. <span class=\"greek\">ἀ. βιβλίον</span>, <strong>abrir um livro em forma de rolo</strong>: Diodoro Sículo 14.55.1; 2Esd 18.5; Dn 7.10; Lc 4.17 v.l.; Ap 5.2ss.; 10.2, 8; compare 2Esd 16.5; TestAbr A 12 p. 91, 22 [Stone p. 30]; Ap 20.12.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Remover uma obstrução, abrir</strong>, transitivo, de selo: Xenofonte, <em>De Rep. Lac.</em> 6.4; SIG 1157, 47 [século I d.C.] <span class=\"greek\">τὰς σφραγῖδας ἀνοιξάτω</span>; Ap 5.9; 6.1–12; 8.1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> <strong>Fazer funcionar, abrir</strong>, transitivo, de partes do corpo. <strong>a.</strong> Boca: <span class=\"greek\">ἀ. τὸ στόμα</span>, <strong>abrir a boca</strong> de outra pessoa, 1Cl 18.15 (Sl 50.17); de peixe, para tirar algo, Mt 17.27; de mudo, Lc 1.64. Abrir a própria boca para falar, frequentemente no AT e em SibOr 3.497, mas também Aristófanes, <em>Av.</em> 1719: Mt 5.2; 6.8 D; At 8.35; 10.34; 18.14; GEb 34, 60. Mais especificamente, <span class=\"greek\">ἐν παραβολαῖς</span>, <strong>falou por parábolas</strong>, Mt 13.35 (Sl 77.2); compare Luciano, <em>Philops.</em> 33. <span class=\"greek\">εἰς βλασφημίας</span>, <strong>abriu a boca para blasfemar</strong>, Ap 13.6. Não abrir a boca, permanecer em silêncio, At 8.32; 1Cl 16.7 (ambos Is 53.7, assim também Melito, <em>P.</em> 64, 462). Figuradamente, da terra que se abre para engolir algo: <span class=\"greek\">ἤνοιξεν ἡ γῆ τὸ στόμα αὐτῆς</span>, Ap 12.16; compare Nm 16.30; 26.10; Dt 11.6.</p>\n<p class=\"entry-text\"><strong>b.</strong> Olhos: <span class=\"greek\">ἀ. τοὺς ὀφθαλμούς</span>, de cego, Is 35.5; 42.7; Tb 11.7; Melito, <em>P.</em> 78, 565; Mt 9.30; 20.33; Jo 9.10, 14, 17, 21, 26, 30, 32; 10.21; B 14.7. Dos próprios olhos, <strong>ver</strong>, Epicteto 2.23.9, 12; PGM 4, 624; At 9.8, 40. Figuradamente, da visão espiritual, Lc 24.31 v.l.; At 26.18; <span class=\"greek\">τοὺς ὀφθαλμοὺς τ. καρδίας</span>, 1Cl 36.2; 59.3; compare Justino, <em>D.</em> 123.2.</p>\n<p class=\"entry-text\"><strong>c.</strong> Ouvidos: Epicteto 2.23.10; PGM 7, 329; de surdo, Mc 7.35. <strong>d.</strong> Coração, figuradamente: <span class=\"greek\">ἀ. τ. καρδίαν πρὸς τ. κύριον</span>, <strong>abrir o coração ao Senhor</strong>, Hv 4.2.4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">6.</span> <strong>Estar em estado de abertura, estar aberto</strong>, intransitivo; somente o 2º perfeito, exceto que o 2º aoristo passivo <span class=\"greek\">ἠνοίγη</span> em At 12.10, veja 1 acima, é praticamente equivalente a intransitivo. Outros exemplos de 2º perfeito: Hipócrates, <em>Morb.</em> 4.39 ed. Littré; VII 558; Plutarco, <em>Mor.</em> 693d, <em>Coriol.</em> 231 [37.2]; Luciano, <em>Nav.</em> 4; Polieno 2.28.1. Na literatura tratada, em contextos que conotam oportunidade: <span class=\"greek\">θύρα μοι ἀνέῳγεν</span>, <strong>uma porta está aberta para mim</strong>, 1Co 16.9; compare Luciano, <em>Soloec.</em> 8 e Justino, <em>D.</em> 7.3. Compare <span class=\"greek\">τ. οὐρανὸν ἀνεῳγότα</span>, Jo 1.51.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">7.</span> <strong>Ser franco, ser aberto</strong>, intransitivo; veja 6 para a referência gramatical e também 5a. <span class=\"greek\">τὸ στόμα ἡμῶν ἀνέῳγεν πρὸς ὑμᾶς</span>, <strong>nossa boca está aberta para vós</strong>, isto é, <strong>falei franca e abertamente</strong>, 2Co 6.11; compare Ez 16.63; 29.21 e <span class=\"greek\">ἄνοιξις</span>. — B. 847. DELG s.v. <span class=\"greek\">οἴγνυμι</span>. M-M.</p>\n</section></article><article id=\"entry-anoikodomeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνοικοδομέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anoikodoméō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀνά</span> + <span class=\"greek\">οἰκοδομέω</span>. Futuro <span class=\"greek\">ἀνοικοδομήσω</span>; 1º aoristo <span class=\"greek\">ἀνῳκοδόμησα</span>, LXX. Passivo: futuro <span class=\"greek\">ἀνοικοδομηθήσομαι</span>, LXX; aoristo <span class=\"greek\">ἀνῳκοδομήθη</span>, Justino, <em>D.</em> 34.7. Heródoto, Aristófanes e posteriores; inscrições, papiros, LXX; TestSol; EpArist 100; Josefo, <em>Ant.</em> 2.203 e outros; Justino, <em>D.</em> 34.7; 80.1, nos sentidos <strong>“construir”</strong> e <strong>“construir novamente”</strong>. <strong>Reconstruir, reedificar.</strong> Éforo, século IV a.C., 70 Fgm. 132 Jac.; PPetr II, 12, 1, 15 [p. 28]; Mitt-Wilck. I/2, 96 VIII, 4; SIG 454, 11s. <span class=\"greek\">τ. σκηνὴν Δαυίδ</span>, <strong>o tabernáculo de Davi</strong>, At 15.16a (Am 9.11); <span class=\"greek\">τὰ κατεστραμμένα αὐτῆς</span>, <strong>suas ruínas</strong>, v. 16b; o templo, B 16.4. <span class=\"greek\">ἀγαπητοὶ ἀνοικοδομεῖσθε</span>, médio, <strong>amados, edificai-vos</strong>, Jd 20 P72. — DELG s.v. <span class=\"greek\">δέμω</span>. M-M.</p>\n</section></article><article id=\"entry-anoixis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄνοιξις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánoixis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνοίγω</span>; desde Tucídides 4.68.5; Plutarco, <em>Mor.</em> 738c <span class=\"greek\">χειλῶν</span>; PGM 5, 285; 36, 312; Josefo, <em>Ant.</em> 18.30. <strong>O ato de abrir, abertura.</strong> <span class=\"greek\">ἵνα μοι δοθῇ λόγος ἐν ἀνοίξει τ. στόματός μου</span>, <strong>para que me seja dada uma mensagem quando eu abrir a boca</strong>, Ef 6.19; compare <span class=\"greek\">ἀνοίγω</span> 7. — DELG s.v. <span class=\"greek\">οἴγνυμι</span>. M-M.</p>\n</section></article><article id=\"entry-anoiso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνοίσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anoísō⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀναφέρω</span>.</p>\n</section></article><article id=\"entry-anoichthesomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνοιχθήσομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anoichthḗsomai⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνοίγω</span>.</p>\n</section></article><article id=\"entry-anomeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνομέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anoméō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἠνόμησα</span>, particípio <span class=\"greek\">ἀνομήσας</span>; passivo, infinitivo <span class=\"greek\">ἀνομηθῆναι</span>, 3Rs 8.32. Veja <span class=\"greek\">ἀνομία</span>. Heródoto 1.144; papiros desde o século III a.C.; LXX; JosAs 12.5; TestLevi 10.3; TestGad 4.1 v.l.; veja Helbing 12; sinônimo <span class=\"greek\">παρανομέω</span>, Suda. <strong>Agir sem lei, pecar.</strong> <span class=\"greek\">εἴς τινα</span> (Nm 32.15; Sl 118.78), <strong>contra alguém</strong>, Hv 1.3.1. Absolutamente, 1Cl 53.2; B 4.8; 14.3, os três em Êx 32.7. <span class=\"greek\">(Ἰωσήφ) ἠνόμησεν σφόδρα</span>, <strong>(José) pecou excessivamente ou flagrantemente</strong>, GJs 15.2. — DELG s.v. 1. <span class=\"greek\">νέμω</span>.</p>\n</section></article><article id=\"entry-anomema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνόμημα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anómēma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνομέω</span>; Stoic. III 136; Diodoro Sículo 1.77.2; 17.5.4; PGM 4, 3099; LXX; En 9.10; TestDan 1.9; TestGad 2.5, v.l. <span class=\"greek\">ἀνομία</span>; Josefo, <em>Ant.</em> 8.251; CSchmidt e WSchubart, <em>Altchr. Texte</em> 1910, p. 111. <strong>Ato ilícito, iniquidade.</strong> Com <span class=\"greek\">ἁμαρτία</span>, Hv 1.3.1; com <span class=\"greek\">ἀνομία</span> e <span class=\"greek\">ἁμαρτία</span>, 1Cl 18.2s. (Sl 50.3s.).</p>\n</section></article><article id=\"entry-anomia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνομία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anomía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Eurípides, Heródoto, pré-socráticos e outros; papiros, LXX, pseudepígrafos, Fílon; Josefo, <em>Bell.</em> 1.493, <em>Ant.</em> 15.348; Ar. 11.7; Justino, <em>D.</em> 14.1; 18.2; 24.3; Atanásio, <em>R.</em> 71.6; Melito, <em>P.</em> 68, 486; Orígenes, <em>C. Cels.</em> 6.44.31; Did., <em>Gen.</em> 44.17.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Estado ou condição de estar disposto ao que é contrário à lei, iniquidade, ilegalidade.</strong> Em oposição a <span class=\"greek\">δικαιοσύνη</span>; compare Heródoto 1.96 e Xenofonte, <em>Mem.</em> 1.2.24, <span class=\"greek\">ἀνομίᾳ μᾶλλον ἢ δικαιοσύνῃ χρώμενοι</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.19a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6.14</a>; Dg 9.5; Hm 4.1.3; com <span class=\"greek\">ὑπόκρισις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.28</a>; frequentemente, como Sl 58.3, com <span class=\"greek\">ἁμαρτία</span>, com a qual é identificada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.4</a>; compare 1Cl 8.3; 18.3 (Sl 50.4; 30.19; 102.10); Hs 7.2. <span class=\"greek\">ἔργα τῆς ἀ.</span>, <strong>atos de iniquidade</strong>, que procedem de uma disposição sem lei, B 4.1; Hs 8.10.3. <span class=\"greek\">υἱοὶ τῆς ἀ.</span>, <strong>pessoas sem lei, aqueles que desprezam a lei</strong>, compare Sl 88.23, Hv 3.6.1; ApcPt 1.3; <span class=\"greek\">διὰ τὴν τῶν ἀνθρώπων ἀ.</span>, AcPl Ha 2.27. <span class=\"greek\">ἀ.</span> caracteriza este éon como domínio de Satanás no final de Marcos do manuscrito Freer.</p>\n<p class=\"entry-text\"><span class=\"greek\">ὁ ἄνθρωπος τῆς ἀ.</span> (v.l. <span class=\"greek\">ἁμαρτίας</span>), <strong>o homem da iniquidade, o Iníquo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.3</a>; considerado tradução de Beliar por Bousset, <em>D. Antichr.</em> 1895, 86; veja também Sl 93.20, <span class=\"greek\">θρόνος ἀνομίας</span>, e compare 1QH 5.36; mas veja BRigaux, <em>Les Épîtres aux Thess.</em> ’56, 656–67. <span class=\"greek\">μυστήριον τῆς ἀ.</span>, <strong>o segredo da iniquidade</strong>, segredo porque — e enquanto — o Anticristo ainda não apareceu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">v. 7</a>; compare <em>Genesis Apocryphon</em> col. I, 2; JFitzmyer, <em>Essays on the Semitic Background of the NT</em> ’71, 103s., n. 9. Sobre a <span class=\"greek\">ἀ.</span> nos últimos dias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.12</a>; D 16.4. <span class=\"greek\">μέθυσμα ἀνομίας</span>, <strong>embriaguez dissoluta</strong>, Hm 8.3. <span class=\"greek\">ἡ τῆς πλάνης ἀ.</span>, <strong>engano iníquo</strong>, B 14.5. <span class=\"greek\">ὁ καιρὸς ὁ νῦν τῆς ἀ.</span>, <strong>o tempo presente, em que reina a iniquidade</strong>, 18.2; compare 15.7 e TestDan 6.6. De Deus, <span class=\"greek\">μισεῖν ἀ.</span> (Sl 44.8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.9</a>, v.l. <span class=\"greek\">ἀδικίαν</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Produto de uma disposição sem lei, ato ilícito, iniquidade.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.19b</a>. <span class=\"greek\">λυτρώσασθαι ἀπὸ πάσης ἀ.</span> (Sl 129.8), <strong>redimir de toda iniquidade</strong>, isto é, de atos ilícitos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2.14</a>. <span class=\"greek\">ἐργάζεσθαι ἀ.</span>, frequente na LXX, <strong>praticar iniquidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.23</a>; Hm 10.3.2; <span class=\"greek\">ἐργάτης ἀ.</span>, 2Cl 4.5; <span class=\"greek\">ἀ. ποιεῖν</span> (Os 6.9; Is 5.7 e outros; TestDan 3.2; TestGad 2.5 v.l.; compare <span class=\"greek\">πράττειν ἀ.</span>, Ar. 11.7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.4</a>; 1Cl 16.10 (Is 53.9); mais especificamente, <span class=\"greek\">ἐν στόματι</span>, <strong>cometer pecado com a boca</strong>, B 10.8; <span class=\"greek\">λαλεῖν ἀ. κατά τινός</span>, <strong>falar iniquamente contra alguém</strong>, 1Cl 15.5 (Sl 34.19); <span class=\"greek\">ἁρπάζειν ἐν ἀ.</span>, <strong>apoderar-se de modo ilícito</strong>, 10.4. De Salomé: <strong>“ai de mim por meu pecado e incredulidade!”</strong>, GJs 20.1, não no papiro.</p>\n<p class=\"entry-text\">No plural, <strong>atos ilícitos, transgressões</strong>: POxy 1121, 20; Herm. Wr. 1.23; frequentemente na LXX; Justino, <em>D.</em> 18.2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4.7</a> (Sl 31.1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8.12</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">10.17</a>; 1Cl 16.5, 9 (Is 53.8); 18.5, 9 (Sl 50.7, 11); 50.6 (Sl 31.1); 60.1; B 5.2 (Is 53.5); Hv 2.2.2; 3.6.4; Hs 5.5.3. Na tradição manuscrita, <span class=\"greek\">ἀ.</span> é frequentemente intercambiado com sinônimos; assim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.9</a> [<span class=\"greek\">ἀδικία</span>]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.3</a> [<span class=\"greek\">ἁμαρτία</span>]; 1Cl 35.5 como v.l. de <span class=\"greek\">πονηρία</span>. — AcPl BMM recto 26 restaurado a partir de POxy 1602, 27, <span class=\"greek\">[ἀν]ομίας</span>; em seu lugar, <span class=\"greek\">ἐπιθυμίας</span> em AcPl Ha 8.20; compare AcPlCor 2.11. — Dodd 76–81. DELG s.v. <span class=\"greek\">νέμω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-anomoios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνόμοιος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anómoios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ὅμοιος</span>; Píndaro, Platão e outros; POxy 237 VI, 29; Sb 5.578; Fílon; Taciano 12.3; Atanásio 8.1. <strong>Diferente, dessemelhante</strong>, com dativo, como Platão, <em>Gorg.</em> 513b e Sb. De uma estrela: <span class=\"greek\">πόθεν ἡ καινότης ἡ ἀ. αὐτοῖς</span>, <strong>de onde poderia vir a novidade, diferente deles — as outras estrelas</strong>, IEph 19.2. — DELG s.v. <span class=\"greek\">ὁμός</span>.</p>\n</section></article><article id=\"entry-anomos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄνομος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánomos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Sófocles, Heródoto, Tucídides e posteriores; IDefixAudollent 188; POxy 237 VII, 11 [século II d.C.]; PGM 58, 9, 11s.; LXX, En, Test12Patr; ParJer 7.24; AscIs; Ar. 15.6; Justino; Atanásio, <em>R.</em> 73.14; Orígenes, <em>C. Cels.</em> 7.63.3, superlativo. <strong>Sem lei, ilegal.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Relativo a comportar-se contrariamente à lei, sem lei, ilegal</strong>, com referência a qualquer lei. <span class=\"greek\">ἄ. κριτής</span>, <strong>juiz injusto</strong>, que nada se importa com a lei, B 20.2; D 5.2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a estar sem vinculação a um código normativo externo, sem lei.</strong> <strong>a.</strong> Quanto à obrigação para com Deus, sem referência a um código moral: <span class=\"greek\">μὴ ὢν ἄ. θεοῦ</span>, <strong>embora eu não esteja livre da obediência a Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.21c</a>, em oposição a <span class=\"greek\">ἔννομος</span>; sobre a construção de <span class=\"greek\">ἄ. θεοῦ</span>, veja Mlt. 236. <strong>b.</strong> Com referência à lei mosaica, usado de gentios como pessoas que não a conhecem, veja 3b, sem crítica implícita: Platão, <em>Pol.</em> 302e [Nägeli 14]; Est 4.17u. <span class=\"greek\">τοῖς ἀ. ὡς ἄ.</span>, <strong>aos sem lei como sem lei</strong>, isto é, <strong>aos gentios como gentio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.21a</a>. Com a expressão <span class=\"greek\">ὡς ἄνομος</span>, v. 21b, Paulo indica empatia pelos que estão fora da tradição mosaica.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Relativo a violar padrões morais, sem lei, ímpio.</strong> <strong>a.</strong> Com referência à lei moral de Deus; daí, <strong>ímpio, perverso</strong> em geral, frequentemente na LXX. Em tratamento pessoal, <span class=\"greek\">ἄνομε</span>, <strong>ó perverso!</strong>, 1Cl 35.9 (Sl 49.21); com <span class=\"greek\">ἀνυπότακτος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.9</a>; com <span class=\"greek\">ἀσεβής</span> — 1Mc 7.5; PGM 58, 11; IDefixAudollent 188 — 1Cl 18.13 (Sl 50.15); Dg 9.4; com <span class=\"greek\">ἄδικος</span>, compare Justino, <em>D.</em> 35.5, <span class=\"greek\">ἀθέους καὶ ἀσεβεῖς καὶ ἀδίκους καὶ ἀνόμους</span>, e PLond II, 358, 13 [150 d.C.], p. 172, <span class=\"greek\">ἄνομα καὶ ἄδικα</span>; 1Cl 56.11 (Jó 5.22). Em oposição a <span class=\"greek\">δίκαιος</span>, Pr 21.18, 1Cl 45.4; compare Dg 9.5; em oposição a <span class=\"greek\">ἅγιος</span>, Dg 9.2. <span class=\"greek\">μετὰ ἀνόμων λογισθῆναι</span>, <strong>ser contado entre os criminosos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.37</a>; SHall, <em>Studia Evangelica</em> ’59, 499–501; compare 1Cl 16.13; os três citam Is 53.12. <span class=\"greek\">ὑπὲρ πᾶσαν ἁμαρτίαν ἀνομώτερος</span>, <strong>perverso além de toda medida</strong>, B 5.9. <span class=\"greek\">τὸ γένος ἄ.</span>, <strong>a raça perversa</strong>, Hs 9.19.1. De coisas: <span class=\"greek\">ἄ. βίος</span>, com <span class=\"greek\">ἄδικος</span>, MPol 3; <span class=\"greek\">ἄ. ἔργα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.8</a>; compare Nicolau de Damasco, 90 Fgm. 58, 2 Jac., <span class=\"greek\">ἔργον ἄνομον ἐργάσασθαι</span>. <span class=\"greek\">ὁ ἄ. καιρός</span>, <strong>tempo perverso</strong>, B 4.9; compare 18.2.</p>\n<p class=\"entry-text\"><strong>b.</strong> Com referência aos que estão fora da tradição legal israelita, veja 2b, e agem contrariamente a seus padrões morais: Sb 17.2; Justino, <em>D.</em> 123.3, <span class=\"greek\">υἱοὶ ἄ.</span>. <span class=\"greek\">διὰ χειρὸς ἀνόμων</span>, <strong>por mãos sem lei</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.23</a>. <span class=\"greek\">ἐκ χειρὸς ἀνόμου</span>, AcPl Ha 8.10; <span class=\"greek\">ἀνόμων</span> em Ox 1602, 2//BMM recto 10; AcPlCor 1.8. <span class=\"greek\">Φαραὼ … ὄντος ἀ.</span>, AcPl Ha 8.12. <span class=\"greek\">οἱ ἄνομοι</span>, MPol 16.1. <span class=\"greek\">τὰ ἄ. ἔθνη</span>, 3Mc 6.9, <strong>os povos sem lei</strong>, 9.2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <span class=\"greek\">ὁ ἄ.</span>, <strong>a personificação da iniquidade, o Iníquo</strong>; Ez 18.24; 33.8; PsSol 17.11; do Iníquo ou Anticristo — veja Ireneu 3.7.2 [Harv. II 26s.] — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.8</a>; compare v. 3. Isso provavelmente explica <span class=\"greek\">ὁ καιρὸς τοῦ ἀ.</span>, <strong>o tempo da iniquidade</strong>, B 15.5; compare 18.2; TestDan 6.6, <span class=\"greek\">ἐν καιρῷ τῆς ἀνομίας</span>. — DELG s.v. <span class=\"greek\">νέμω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-anomos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνόμως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anómōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de <span class=\"greek\">ἄνομος</span>; Eurípides, Tucídides e outros; PMagd 6, 11; BGU 1200, 20; 2Mc 8.17; Fílon, <em>Leg. All.</em> 1.35 v.l.; Josefo, <em>C. Ap.</em> 1.147, <em>Ant.</em> 15.59. <strong>Sem participação num sistema jurídico organizado, sem lei.</strong> <span class=\"greek\">ὅσοι ἀ. ἥμαρτον ἀ. καὶ ἀπολοῦνται</span>, <strong>aqueles que pecaram sem lei também perecerão sem lei</strong>, isto é, os que pecam sem conhecimento da lei mosaica — formulado do ponto de vista da condição privilegiada de Israel — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.12</a>; equivale a <span class=\"greek\">χωρὶς νόμου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">7.9</a>. Compare Isócrates 4.39, <span class=\"greek\">ἀ. ζῆν</span> = <strong>viver sem a vantagem de uma lei organizada</strong>, isto é, sem pólis, não civilizado, formulado do ponto de vista da realização ateniense. Para o termo <span class=\"greek\">ἀ.</span> e o tema da vantagem relativa, veja também Josefo, <em>C. Ap.</em> 2.151. Sinônimo <span class=\"greek\">ἀτάκτως</span>, q.v.</p>\n</section></article><article id=\"entry-anoneidistos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνονειδίστως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anoneidístōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de <span class=\"greek\">ἀνονείδιστος</span>; Nicolau de Damasco, 90 Fgm. 130, 62, p. 403, 14 Jac., <span class=\"greek\">ἀνονείδιστα</span>. <strong>Sem censurar, sem lançar em rosto</strong>, com <span class=\"greek\">ἀδιστάκτως</span>: <span class=\"greek\">χορηγεῖν τινι</span>, <strong>dar a alguém</strong>, Hs 9.24.2. — DELG s.v. <span class=\"greek\">ὄνειδος</span>.</p>\n</section></article><article id=\"entry-anonetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνόνητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anónētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">αν-</span> privativo + <span class=\"greek\">ὀνητός</span>, <strong>“proveitoso”</strong>; veja <span class=\"greek\">ὀνίναμαι</span>. Sófocles, Platão e outros; Mitt-Wilck. II/2, 88 IV, 9; PPrinc 119, 56 [século IV d.C.]; Sb 3.11; 4Mc 16.7, 9; Josefo, <em>Bell.</em> 1.464, <em>Vi.</em> 422 e outros. <strong>Inútil.</strong> <span class=\"greek\">ἐπιθυμίαι ἀ.</span>, com <span class=\"greek\">βλαβεραί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6.9</a> v.l., em lugar de <span class=\"greek\">ἀνοήτους</span>. — DELG s.v. <span class=\"greek\">ὀνίνημι</span>.</p>\n</section></article><article id=\"entry-anorthoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνορθόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anorthóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀνορθώσω</span>; 1º aoristo <span class=\"greek\">ἀνώρθωσα</span>, LXX. Passivo: aoristo <span class=\"greek\">ἀνωρθώθη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.13</a>, v.l. <span class=\"greek\">ἀνορθώθη</span>; veja B-D-F §67, 2; Helbing 72s.; perfeito, particípio <span class=\"greek\">ἀνωρθωμένος</span>, LXX. De <span class=\"greek\">ὀρθόω</span>, <strong>“pôr direito”</strong>; Eurípides, Heródoto e posteriores; LXX; ApcEsdr p. 26, 15 Tdf.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Reconstruir algo depois que caiu, reconstruir, restaurar.</strong> Heródoto 1.19, <span class=\"greek\">τὸν νηόν</span>; OGI 710, 3s. [século II d.C.], <span class=\"greek\">τὸ π[ρ]οπύλα[ιον] | χρόνῳ [διαφθαρὲ]ν [ἀ]νώρθωσεν</span>; 2Rs 7.26 v.l.; 1Cr 17.24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.16</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Tornar-se ereto a partir de uma posição curvada, endireitar-se.</strong> Da mulher encurvada que foi curada, passivo com sentido ativo: <span class=\"greek\">ἀνωρθώθη</span>, <strong>ela tornou a ficar ereta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.13</a>; compare JosAs 11, final [p. 54, 18 Bat.], cód. A; <span class=\"greek\">ἐπὶ τὰ γόνατα</span>, compare Hobart 22. <span class=\"greek\">τὰ παραλελυμένα γόνατα ἀ.</span>, <strong>fortalecei vossos joelhos enfraquecidos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.12</a>. — DELG s.v. <span class=\"greek\">ὀρθός</span>. M-M.</p>\n</section></article><article id=\"entry-anosios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνόσιος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anósios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ὅσιος</span>; Ésquilo, Heródoto e posteriores. <strong>Relativo a estar em oposição a Deus ou ao que é sagrado, profano, ímpio.</strong> A concepção de que certas ações tornam seres ou lugares santos interditos a seus agentes favorece a conotação de torpeza moral: <strong>perverso</strong>, isto é, revoltante para Deus ou para uma pessoa de boa disposição. Para várias perspectivas, veja <span class=\"greek\">ἁγνεία</span> e a literatura ali citada; sobre o assunto, especialmente Platão, <em>Leg.</em> 4.716d, citado em SIG 983 n. 3.</p>\n<p class=\"entry-text\"><strong>a.</strong> De pessoas: PBrem 1, 4 [116 d.C.] = CPJ 438, 4; PGiss 41 II, 4 [117 d.C.] = CPJ 443 II, 4, em ambos <span class=\"greek\">ἀνόσιοι Ἰουδαῖοι</span>; PGM 4, 2476; 2Mc 7.34; 8.32; 4Mc 12.11; EpArist 289; Justino, <em>A I</em> 5.4, <span class=\"greek\">δαίμονας</span>; Atanásio 32.1, <span class=\"greek\">Δία</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.9</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3.2</a>; com <span class=\"greek\">ἄνομος</span>, 1Cl 45.4; AcPl Ha 8.12.</p>\n<p class=\"entry-text\"><strong>b.</strong> De coisas: Diodoro Sículo 34+35, Fgm. 14, <span class=\"greek\">πρᾶξις</span>; PThead 21, 15, <span class=\"greek\">πρᾶγμα</span>; Sb 12.4; 3Mc 5.8; Justino, <em>D.</em> 108.2; Atanásio 1.2. <span class=\"greek\">ἀ. στάσις</span>, <strong>discórdia profana</strong>, 1Cl 1.1. <span class=\"greek\">αἰκίσματα δεινὰ καὶ ἀ.</span>, <strong>torturas terríveis e perversas</strong>, 6.2. — DELG s.v. <span class=\"greek\">ὅσιος</span>. M-M. TW.</p>\n</section></article><article id=\"entry-anoche-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνοχή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anochḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνέχω</span>; Xenofonte e outros. Literalmente, <strong>“um refrear, uma suspensão”</strong>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Estado de alívio de algo oneroso ou desagradável, alívio, trégua.</strong> 1Mc 12.25; Josefo, <em>Bell.</em> 1.173, <em>Ant.</em> 6.72; com <span class=\"greek\">ἔχειν</span>, Diodoro Sículo 11.36.4, <span class=\"greek\">ἀνοχὴν ἔχειν</span>; POxy 1068, 15, <span class=\"greek\">ἡμερῶν ἀνοχὴν ἔχω</span>. <span class=\"greek\">ἀνοχὴν οὐκ ἔχειν</span>, <strong>não ter alívio</strong>, Hs 6.3.1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Cessação temporária, pausa.</strong> Josefo, <em>Ant.</em> 6.72. <span class=\"greek\">ἀ. τῆς οἰκοδομῆς</span>, <strong>uma pausa na construção</strong>, Hs 9.5.1; 9.14.2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Ato de suportar com paciência, tolerância, clemência, indulgência.</strong> Epicteto 1.29.62, <span class=\"greek\">ἀ. ἔχω</span>, <strong>gozo de clemência</strong>; En 13.2; PSI 632, 13 [século III a.C.]; compare Nägeli 45. <span class=\"greek\">ἐν τῇ ἀ. τοῦ θεοῦ</span>, <strong>na tolerância de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.26</a>. Para expressão negativa dessa ideia, veja SIG 985, 34s. [século I d.C.], <span class=\"greek\">καὶ τοὺς παραβαίνοντας τὰ παραγ[γέλματα οὐκ ἀνέ]ξονται</span>, dito dos grandes deuses; FDanker em <em>Gingrich Festschr.</em> ’72, 102s. Com <span class=\"greek\">μακροθυμία</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.4</a>. — DELG s.v. 1. <span class=\"greek\">ἔχω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-antagonizomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνταγωνίζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦antagōnízomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀντί</span> + <span class=\"greek\">ἀγωνίζομαι</span>; Tucídides e outros; 4Mc 17.14; Josefo, <em>C. Ap.</em> 1.56; com <span class=\"greek\">πρός τινα</span>, IPriene 17, 15 [século III a.C.]. <strong>Lutar, combater.</strong> <span class=\"greek\">ἀ. πρὸς τ. ἁμαρτίαν</span>, <strong>em vosso combate/luta contra o pecado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.4</a>. — DELG s.v. <span class=\"greek\">ἄγω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-antakouo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀντακούω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦antakoúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀντακούσομαι</span>; veja <span class=\"greek\">ἀκούω</span>. Trágicos e outros; Xenofonte, <em>An.</em> 2.5.16; Filóstrato, <em>Imag.</em> 1.28, p. 333, 24; PLond 1708, 57. <strong>Ouvir por sua vez, ouvir em resposta.</strong> <span class=\"greek\">ὁ τὰ πολλὰ λέγων καὶ ἀντακούσεται</span>, <strong>quem fala muito também ouvirá muito em resposta</strong>, 1Cl 30.4 (Jó 11.2).</p>\n</section></article><article id=\"entry-antallage-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνταλλαγή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦antallagḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Maximus Tyr. 39.1c v.l.; PCol IV, 100, 12 [século III a.C.]; Hesíquio; Simplício, <em>in Aristot., Phys.</em> 1350, 32, numa definição de <span class=\"greek\">ἀντιπερίστασις</span>, <strong>intercâmbio</strong>, explica-o como <strong>“troca [<span class=\"greek\">ἀνταλλαγή</span>] de lugares feita quando um corpo é expulso por outro”</strong>; Theophilus Antecessor [século VI d.C.] 2.6, p. 281 [ed. OReitz 1751]; outras referências em DGE. <strong>Troca.</strong> <span class=\"greek\">ὢ τῆς γλυκείας ἀ.</span>, <strong>ó doce troca!</strong>, de pecadores tornando-se justos, Dg 9.5. — DELG s.v. <span class=\"greek\">ἄλλος</span>.</p>\n</section></article><article id=\"entry-antallagma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀντάλλαγμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦antállagma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Eurípides e outros; Rt 4.7; Jó 28.15; Jr 15.13; Sir 6.15; Fílon, Fgm. 110 Harris; Josefo, <em>Bell.</em> 1.355, <em>Ant.</em> 14.484. <strong>Algo dado em troca, compensação.</strong> <span class=\"greek\">τί δώσει ἄνθρωπος ἀ. τ. ψυχῆς αὐτοῦ;</span>, <strong>que dará uma pessoa em troca de sua alma?</strong>; não há nada que possa compensar perda tão grande, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.37</a>. — DELG s.v. <span class=\"greek\">ἄλλος</span>. TW.</p>\n</section></article><article id=\"entry-antanairo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνταναιρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦antanairéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro, 2ª sg. <span class=\"greek\">ἀντανελεῖς</span>, Sl 103.29; 2º aoristo <span class=\"greek\">ἀντανεῖλον</span>. Passivo: futuro <span class=\"greek\">ἀνταναιρεθήσομαι</span>, LXX; 1º aoristo <span class=\"greek\">ἀντανῃρέθην</span>. Veja <span class=\"greek\">ἀναιρέω</span>; Demóstenes e outros; papiros, LXX. <strong>Tirar como punição</strong>, <span class=\"greek\">τί ἀπό τινος</span>, <strong>algo de alguém</strong>, 1Cl 18.11 (Sl 50.13). — DELG s.v. <span class=\"greek\">αἱρέω</span>.</p>\n</section></article><article id=\"entry-antanapleroo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνταναπληρόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦antanaplēróō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Demóstenes 14.16 e 17; Cássio Dio 44.48.2; Apolônio Díscolo, <em>Synt.</em> p. 14, 1; 114, 7s. e outros [p. 21, 5; 158, 1 e outros]. <strong>Tomar sua vez em preencher algo</strong>; para a força recíproca de <span class=\"greek\">ἀντί</span>, compare Xenofonte, <em>Hell.</em> 2.4.11 e 12, <span class=\"greek\">ἐμπίπλημι … ἀντεμπίπλημι</span>: um grupo de soldados enche uma estrada, e um segundo grupo forma outra linha. Daí, <strong>completar por sua parte, suprir</strong>.</p>\n<p class=\"entry-text\"><span class=\"greek\">τὰ ὑστερήματα τῶν θλίψεων τοῦ Χριστοῦ</span>, <strong>suprir o que falta nas tribulações de Cristo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.24</a>. Sobre a inevitabilidade de sofrimentos suportados por causa do testemunho de Cristo, dos quais resultam vários benefícios, compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">4.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3.3</a>. Paulo se alegra em suprir aquilo que seu Mestre lhe deixou para sofrer; veja Fócio, <em>Ep.</em> 253, p. 190–93, especialmente p. 193, 77–82. Depois de receber sua incumbência apostólica, Paulo assume o fardo de sofrimentos que recairiam sobre Cristo caso este empreendesse pessoalmente a missão apostólica. Veja Lightfoot, comentário <em>ad loc.</em>, para discussão detalhada dessa interpretação.</p>\n<p class=\"entry-text\">Para outras interpretações, inclusive referência aos <strong>“ais messiânicos”</strong>, veja PO’Brien, <em>WBC: Colossians, Philemon</em>, ’82, <em>ad loc.</em>; veja também WMoir, Cl 1.24: <em>ET</em> 42, ’31, 479s.; EPercy, <em>Die Probleme der Kolosser-und Epheserbriefe</em> ’46, 128–34; ELohse, <em>Märtyrer u. Gottesknecht</em> ’55, 202ss.; JKremer, <em>Was an den Leiden Christi noch mangelt</em>: <em>Bonner Biblische Beiträge</em> 12, ’56; HGustafson, <em>Biblical Research</em> 8, ’63, 28–42, e literatura em <span class=\"greek\">πάθημα</span> 1. Veja <span class=\"greek\">θλῖψις</span>. — DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M.</p>\n</section></article>"};
